<?php
namespace Support\Component\Supportplans\Site\Controller;
\defined('_JEXEC') or die;
use Joomla\CMS\Factory;
use Joomla\CMS\Component\ComponentHelper; use Joomla\CMS\MVC\Controller\BaseController; use Joomla\CMS\Router\Route; use Joomla\CMS\Session\Session;
class ServiceplanController extends BaseController {
 public function add():void{Factory::getApplication()->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&mode=new&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));} public function cancel():void{Factory::getApplication()->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));} public function apply():void{$this->store('apply');} public function save():void{$this->store('close');} public function save2new():void{$this->store('new');}
 private function store(string $after):void{Session::checkToken() or jexit('Invalid Token');$app=Factory::getApplication();$in=$app->input;$db=Factory::getContainer()->get('DatabaseDriver');$id=$in->getInt('id');$name=trim($in->getString('name'));$mode=$in->getCmd('billing_mode','prepaid');if(!in_array($mode,['prepaid','ongoing','subscription'],true))$mode='prepaid';$min=max(1,$in->getInt('min_minutes',30));$step=max(1,$in->getInt('step_minutes',5));$desc=trim($in->getString('description'));$pdfTitle=trim($in->getString('pdf_title'));$pdfSectionTitle=trim($in->getString('pdf_section_title'));$pdfWorkTitle=trim($in->getString('pdf_work_title'));$pdfFooterTitle=trim($in->getString('pdf_footer_title'));$pub=$in->getInt('published',1)?1:0;if($mode==='ongoing'){$months=1;$minutes=0;$cost=0;$rate=max(0,$in->getFloat('hourly_rate',0));}elseif($mode==='subscription'){$months=max(1,$in->getInt('subscription_months',1));$minutes=0;$cost=max(0,$in->getFloat('total_cost',300));$rate=0;$min=1;$step=1;}else{$months=1;$hours=max(.083333,$in->getFloat('hours',1));$minutes=max(5,(int)round($hours*60));$cost=max(0,$in->getFloat('prepaid_total_cost',0));$rate=$minutes>0?$cost/($minutes/60):0;}if($name===''){$app->enqueueMessage('Συμπληρώστε το όνομα του πλάνου.','error');$app->redirect(Route::_($id?'index.php?option=com_supportplans&view=serviceplans&tmpl=component&id=' . $id . '&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)):'index.php?option=com_supportplans&view=serviceplans&tmpl=component&mode=new&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));return;}$fields=['name'=>$name,'billing_mode'=>$mode,'hourly_rate'=>$rate,'subscription_months'=>$months,'total_minutes'=>$minutes,'total_cost'=>$cost,'min_minutes'=>$min,'step_minutes'=>$step,'description'=>$desc,'pdf_title'=>$pdfTitle,'pdf_section_title'=>$pdfSectionTitle,'pdf_work_title'=>$pdfWorkTitle,'pdf_footer_title'=>$pdfFooterTitle,'published'=>$pub];if($id){$sets=[];foreach($fields as $k=>$v)$sets[]=$db->quoteName($k).'='.(is_string($v)?$db->quote($v):(float)$v);$sets[]=$db->quoteName('modified').'='.$db->quote(Factory::getDate()->toSql());$q=$db->getQuery(true)->update($db->quoteName('#__supportplans_serviceplans'))->set($sets)->where('id='.(int)$id);$db->setQuery($q)->execute();}else{$cols=array_keys($fields);$cols[]='created';$vals=[];foreach($fields as $v)$vals[]=is_string($v)?$db->quote($v):(float)$v;$vals[]=$db->quote(Factory::getDate()->toSql());$q=$db->getQuery(true)->insert($db->quoteName('#__supportplans_serviceplans'))->columns($db->quoteName($cols))->values(implode(',',$vals));$db->setQuery($q)->execute();$id=(int)$db->insertid();}$app->enqueueMessage('Το πλάνο αποθηκεύτηκε.');if($after==='close'){$app->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));return;}if($after==='new'){$app->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&mode=new&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));return;}$app->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&id=' . $id . '&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)),false));}
 public function delete():void{Session::checkToken() or jexit('Invalid Token');$app=Factory::getApplication();$db=Factory::getContainer()->get('DatabaseDriver');$id=$app->input->getInt('id');$q=$db->getQuery(true)->select('COUNT(*)')->from($db->quoteName('#__supportplans_plans'))->where('service_plan_id='.(int)$id);if((int)$db->setQuery($q)->loadResult()>0)$app->enqueueMessage('Το πλάνο χρησιμοποιείται και δεν μπορεί να διαγραφεί.','warning');else{$q=$db->getQuery(true)->delete($db->quoteName('#__supportplans_serviceplans'))->where('id='.(int)$id);$db->setQuery($q)->execute();}$app->redirect(Route::_('index.php?option=com_supportplans&view=serviceplans&tmpl=component&Itemid=' . max(1,(int) ComponentHelper::getParams('com_supportplans')->get('standalone_itemid',785)) . '',false));}
}